mapper.select:
select id, supplier_id, AVG( average_price ) AS average_price, MIN( lower_price ) AS lower_price, MAX( highest_price ) AS highest_price, SUM( pork_arrange_slices ) AS pork_arrange_slices, SUM( deal_slices ) AS deal_slices, SUM( pork_arrange_weight ) AS pork_arrange_weight, SUM( deal_weight ) AS deal_weight, SUM( amount ) AS amount, SUM( commission ) AS commission, statistics_date from `meattrade_statistics` -- left join `order` o on s.merchant_id = o.merchant_id -- left join `order_detail` od on o.id = od.order_id -- left join `pork_arrange_detail` `pad` o `pad`.id = od.pork_arrange_detail_id
and supplier_id = #{param.supplierId}
and statistics_date between #{param.startTime} and #{param.endTime}
and supplier_id in
#{supplierId}
group by supplier_id
order by ${param.item} ${param.sort}

select pr.supplier_id, sum(pa.slices) AS pork_arrange_slices, sum(pa.weight) AS pork_arrange_weight from meattrade_pork_arrange pa INNER JOIN meattrade_pork_report pr on pa.pork_report_id = pr.id INNER JOIN meattrade_pork_arrange_audit paa on paa.pork_arrange_id = pa.id and paa.audit_status = 'PASSED'
and pr.supplier_id = #{param.supplierId}
and pa.create_time between #{param.startTime} and #{param.endTime}
and pr.supplier_id in
#{supplierId}
group by pr.supplier_id order by pa.slices desc

select pr.supplier_id, sum(pa.slices) AS pork_arrange_slices, sum(pa.weight) AS pork_arrange_weight from meattrade_pork_arrange pa INNER JOIN meattrade_pork_report pr on pa.pork_report_id = pr.id INNER JOIN meattrade_pork_arrange_audit paa on paa.pork_arrange_id = pa.id and paa.audit_status = 'PASSED'
and pr.supplier_id = #{param.supplierId}
and pa.create_time between #{param.startTime} and #{param.endTime}
and pr.supplier_id in
#{supplierId}
group by pr.supplier_id order by pa.slices desc

select pr.supplier_id, sum(pa.slices) AS pork_arrange_slices, sum(pa.weight) AS pork_arrange_weight, pr.goods_category_id, pr.goods_category_name from meattrade_pork_arrange pa INNER JOIN meattrade_pork_report pr on pa.pork_report_id = pr.id INNER JOIN meattrade_pork_arrange_audit paa on paa.pork_arrange_id = pa.id and paa.audit_status = 'PASSED'
and pr.supplier_id = #{param.supplierId}
and pa.create_time between #{param.startTime} and #{param.endTime}
and pr.supplier_id in
#{supplierId}
group by pr.supplier_id,pr.goods_category_id order by pa.slices desc

select pr.supplier_id, sum(pa.slices) AS pork_arrange_slices, sum(pa.weight) AS pork_arrange_weight, pr.goods_category_id, pr.goods_category_name from meattrade_pork_arrange pa INNER JOIN meattrade_pork_report pr on pa.pork_report_id = pr.id INNER JOIN meattrade_pork_arrange_audit paa on paa.pork_arrange_id = pa.id and paa.audit_status = 'PASSED'
and pr.supplier_id = #{param.supplierId}
and pa.create_time between #{param.startTime} and #{param.endTime}
and pr.supplier_id in
#{supplierId}
group by pr.supplier_id,pr.goods_category_id order by pa.slices desc

select o.supplier_id, max(d.unit_price) AS highest_price, min(d.unit_price) AS lower_price, count(d.id) AS deal_slices, sum(d.weight) AS deal_weight, sum(d.price) AS amount, sum(d.commission) as commission from meattrade_order o left join meattrade_order_detail d on d.order_id = o.id
o.status = 'FINISHED'
and o.supplier_id = #{param.supplierId}
and d.create_time between #{param.startTime} and #{param.endTime}
and o.supplier_id in
#{supplierId}
group by o.supplier_id

select o.supplier_id, max(d.unit_price) AS highest_price, min(d.unit_price) AS lower_price, d.goods_category_id, d.goods_category_name, count(d.id) AS deal_slices, sum(d.weight) AS deal_weight, sum(d.price) AS amount, sum(d.commission) as commission from meattrade_order o left join meattrade_order_detail d on d.order_id = o.id
o.status = 'FINISHED'
and o.supplier_id = #{param.supplierId}
and d.create_time between #{param.startTime} and #{param.endTime}
and o.supplier_id in
#{supplierId}
group by o.supplier_id,d.goods_category_id

select o.supplier_id, prd.pork_report_code, prd.goods_category_id, prd.goods_category_name, prd.fresh_label, count( d.id ) AS deal_slices, SUM( d.weight ) AS deal_weight, SUM( d.price ) AS amount, SUM( d.commission ) AS commission, DATE_FORMAT(o.update_time,'%Y-%m-%d') AS statisticsDate from meattrade_order o left join meattrade_order_detail d on d.order_id = o.id left join meattrade_pork_arrange_detail prd on d.pork_arrange_detail_id = prd.id
o.status = 'FINISHED'
and d.create_time between #{param.period.begin} and #{param.period.end}
and o.supplier_id = #{param.supplierId}
group by prd.pork_report_code,o.id,DATE_FORMAT(o.update_time,'%Y-%m-%d')
